// One item per hotel served by this n8n instance (comma-separated env var).
return ($env.ZARIN_HOTEL_IDS || '').split(',').map((h) => h.trim()).filter(Boolean)
  .map((hotelId) => ({ json: { hotelId } }));

// Signs a request for the Zarin Integration API.
// With ZARIN_KEY_ID and ZARIN_KEY_SECRET set (a scoped key from `npm run integration-key`):
//   HMAC-SHA256(keySecret, `${timestamp}.${nonce}.${body}`), a fresh nonce per request (v2).
// Otherwise the shared secret: HMAC-SHA256(ZARIN_INTEGRATION_SECRET, `${timestamp}.${body}`) (v1).
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance.
const crypto = require('crypto');
const keyId = $env.ZARIN_KEY_ID || '';
const keySecret = $env.ZARIN_KEY_SECRET || '';
const scoped = Boolean(keyId && keySecret);
const sign = (json) => {
  const body = json.requestBody ? JSON.stringify(json.requestBody) : '';
  const timestamp = Math.floor(Date.now() / 1000);
  const nonce = scoped ? crypto.randomBytes(16).toString('hex') : '';
  const signature = crypto
    .createHmac('sha256', scoped ? keySecret : $env.ZARIN_INTEGRATION_SECRET)
    .update(scoped ? `${timestamp}.${nonce}.${body}` : `${timestamp}.${body}`)
    .digest('hex');
  return { ...json, rawBody: body, zarinTimestamp: String(timestamp), zarinSignature: signature, zarinKeyId: scoped ? keyId : '', zarinNonce: nonce };
};
return $input.all().map((item) => ({ json: sign(item.json) }));

// Purchase orders past their expected day (approved or sent, not received). The API answers
// with an array, which n8n splits into one item per order: grouped back per hotel here.
// One in-app notification per hotel to the inventory manager and the GM; the dedupe key holds
// the day and the late orders, so a repeat run the same day is skipped by the backend.
const day = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Tehran' });
const byHotel = new Map();
for (const [i, item] of $input.all().entries()) {
  const o = item.json;
  if (!o || !o.purchaseOrderId) continue; // an empty answer
  const hotelId = $('Sign request').itemMatching(i).json.hotelId;
  if (!byHotel.has(hotelId)) byHotel.set(hotelId, []);
  byHotel.get(hotelId).push(o);
}
const out = [];
for (const [hotelId, late] of byHotel) {
  const lines = late.slice(0, 5).map((o) => `• ${o.supplierName || '—'}: ${o.daysLate} روز تأخیر (${(o.lines || []).length} قلم)`);
  out.push({ json: {
    hotelId,
    baleText: `📦 ${late.length} سفارش خرید از موعد تحویل گذشته\n${lines.join('\n')}`,
    requestBody: {
      roles: ['inventoryManager', 'generalManager'],
      title: `${late.length} سفارش خرید دیر کرده است`,
      body: lines.join('\n'),
      severity: 'warning',
      category: 'inventory',
      route: '/inventory',
      dedupeKey: `po-overdue:${day}:${late.map((o) => o.purchaseOrderId).sort().join(',')}`,
      dedupeHours: 20,
    },
  } });
}
return out;

